//! `papers.latexenc`: LaTeX by the character table of papers (`data/latex-characters.tsv`,
//! the table of design/data of papers; the Rust of it is generated by `tools/gen_latexenc.py`).
//!
//! [`string_to_latex`] is what `check --encoding latex` writes. The text that
//! papers compares (names, titles, file names) is decoded by [`super::latex`],
//! the values of an entry (`--encoding unicode`, `add`, the export formats) by
//! pylatexenc, in [`super::unicode`].

use std::collections::HashMap;
use std::sync::OnceLock;

use super::latexenc_tables::UNICODE_TO_LATEX;

fn latex_map() -> &'static HashMap<char, &'static str> {
    static MAP: OnceLock<HashMap<char, &'static str>> = OnceLock::new();
    // dict(unicode_to_latex): a later row of a character replaces an earlier one
    MAP.get_or_init(|| UNICODE_TO_LATEX.iter().copied().collect())
}

/// A string as LaTeX: each character by the table, but the spaces and braces (`string_to_latex`).
pub fn string_to_latex(string: &str) -> String {
    let map = latex_map();
    let mut out = String::with_capacity(string.len());
    for c in string.chars() {
        match c {
            ' ' | '{' | '}' => out.push(c),
            c => match map.get(&c) {
                Some(latex) => out.push_str(latex),
                None => out.push(c),
            },
        }
    }
    out
}

/// Protect the capitals of a title: `Hello` as `{H}ello` (`protect_uppercase`).
pub fn protect_uppercase(string: &str) -> String {
    // re.sub('([^{]|^)([A-Z])([^}]|$)', r'\g<1>{\g<2>}\g<3>', string)
    let c: Vec<char> = string.chars().collect();
    let n = c.len();
    let matched = |p: usize| -> Option<(String, char, String, usize)> {
        let upper = |i: usize| i < n && c[i].is_ascii_uppercase();
        let g3 = |r: usize| -> Option<(String, usize)> {
            if r < n && c[r] != '}' {
                Some((c[r].to_string(), r + 1))
            } else if r == n {
                Some((String::new(), r))
            } else {
                None
            }
        };
        // `[^{]`, then `^`
        if p < n
            && c[p] != '{'
            && upper(p + 1)
            && let Some((g, end)) = g3(p + 2)
        {
            return Some((c[p].to_string(), c[p + 1], g, end));
        }
        if p == 0
            && upper(0)
            && let Some((g, end)) = g3(1)
        {
            return Some((String::new(), c[0], g, end));
        }
        None
    };
    let mut out = String::new();
    let mut i = 0;
    while i < n {
        match matched(i) {
            Some((g1, g2, g3, end)) => {
                out.push_str(&g1);
                out.push('{');
                out.push(g2);
                out.push('}');
                out.push_str(&g3);
                i = end;
            }
            None => {
                out.push(c[i]);
                i += 1;
            }
        }
    }
    out
}
